<?php
declare(strict_types=1);
session_start();
$pdo=null;$error='';$notice='';$rows=[];$csrf=$_SESSION['passenger_csrf']??=bin2hex(random_bytes(32));
if(is_file(__DIR__.'/config.local.php')){require __DIR__.'/config.local.php';try{$pdo=new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}catch(Throwable $e){$error='No se pudo conectar con la base de datos. Revisa la configuración.';}}
function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if($_SERVER['REQUEST_METHOD']==='POST'&&$pdo){if(!hash_equals($csrf,(string)($_POST['csrf']??''))){$error='La sesión venció. Recarga la página e inténtalo otra vez.';}else{try{$action=$_POST['action']??'';if($action==='save'){$name=trim((string)($_POST['name']??''));$dni=trim((string)($_POST['dni']??''));$age=(int)($_POST['age']??0);if($name===''||mb_strlen($name)>160||!preg_match('/^[0-9]{8}$/',$dni)||$age<1||$age>120){$error='Completa el nombre, un DNI de 8 dígitos y una edad entre 1 y 120.';}else{$q=$pdo->prepare('INSERT INTO passengers(dni,full_name,age) VALUES(?,?,?)');$q->execute([$dni,$name,$age]);$notice='Pasajero registrado correctamente.';}}elseif($action==='delete'){$id=(int)($_POST['id']??0);$q=$pdo->prepare('SELECT COUNT(*) FROM tickets WHERE passenger_id=?');$q->execute([$id]);if((int)$q->fetchColumn()>0){$error='No se puede borrar: esta persona tiene boletos asociados.';}else{$q=$pdo->prepare('DELETE FROM passengers WHERE id=?');$q->execute([$id]);$notice='Registro de pasajero eliminado.';}}}catch(PDOException $e){$error=$e->getCode()==='23000'?'Ese DNI ya está registrado o el registro tiene información asociada.':'No se pudo guardar el registro.';}catch(Throwable $e){$error='No se pudo completar la operación.';}}}
if($pdo){$rows=$pdo->query('SELECT p.id,p.dni,p.full_name,p.age,(SELECT COUNT(*) FROM tickets t WHERE t.passenger_id=p.id) ticket_count FROM passengers p ORDER BY p.id DESC LIMIT 200')->fetchAll();}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pasajeros · Ruta Norte</title><link rel="stylesheet" href="assets/app.css?v=20261028"></head><body><header class="top"><a class="brand" href="index.php"><span class="brand-icon">RN</span> RUTA<span>NORTE</span></a><nav><a href="index.php">Buscar viajes</a><a href="manifiesto.php">Embarque</a><a href="reportes.php">Reportes</a><a class="active" href="pasajeros.php">Pasajeros</a><a href="simulador.php">Simulador</a></nav><div class="user"><span class="avatar">JV</span><span>Jhonny Vega<small>Registro de pasajeros</small></span></div></header><main class="subpage"><div class="eyebrow"><i></i> REGISTRO DE PERSONAS</div><h1>Pasajeros</h1><p class="muted">Registra y administra los datos de las personas que viajarán.</p><?php if($error):?><div class="notice"><?=h($error)?></div><?php endif;?><?php if($notice):?><div class="notice success"><?=h($notice)?></div><?php endif;?><?php if(!$pdo):?><div class="notice">Configura la base de datos para registrar pasajeros.</div><?php else:?><section class="passenger-form"><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="save"><label>NOMBRE COMPLETO<input name="name" maxlength="160" required placeholder="Ej. Ana Pérez"></label><label>DNI<input name="dni" inputmode="numeric" maxlength="8" pattern="[0-9]{8}" required placeholder="8 dígitos"></label><label>EDAD<input name="age" type="number" min="1" max="120" required placeholder="Edad"></label><button class="search-btn">Guardar pasajero</button></form></section><div class="demo-count">Personas registradas: <b><?=count($rows)?></b> <small>(máximo 200 mostradas)</small></div><div class="manifest passenger-table"><div class="manifest-row manifest-title"><span>Nombre completo</span><span>DNI</span><span>Edad</span><span>Boletos</span><span>ID</span><span>Acción</span></div><?php foreach($rows as $p):?><div class="manifest-row"><span><?=h($p['full_name'])?></span><span><?=h($p['dni'])?></span><span><?=h($p['age']??'—')?></span><span><?=h($p['ticket_count'])?></span><span><?=h($p['id'])?></span><form method="post" onsubmit="return confirm('¿Borrar este registro de pasajero?')"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="danger-link" <?=((int)$p['ticket_count']>0?'disabled title="Tiene boletos asociados"':'')?>>Borrar</button></form></div><?php endforeach;?><?php if(!$rows):?><div class="empty">Todavía no hay pasajeros registrados.</div><?php endif;?></div><?php endif;?></main><footer><span>© 2026 Ruta Norte</span><span>Registro de pasajeros</span><span>Los boletos asociados se conservan</span></footer></body></html>
